#!/usr/bin/env python3

from xarray.core.merge import merge_attrs

def test_none_in_variable_attrs():
    """Test what happens if variable_attrs contains None"""
    print("Testing None in variable_attrs...")

    try:
        # This might happen if one of the variables has None as attrs
        result = merge_attrs([None, {'a': 'b'}], 'override')
        print(f"Result with None first: {result}")
    except Exception as e:
        print(f"Error with None first: {e}")

    try:
        result = merge_attrs([{'a': 'b'}, None], 'override')
        print(f"Result with None second: {result}")
    except Exception as e:
        print(f"Error with None second: {e}")

if __name__ == "__main__":
    test_none_in_variable_attrs()
